//! Right-click "Sort with AutoSort" in the file manager.
//!
//! * macOS: a Finder Quick Action (Automator workflow) in `~/Library/Services`
//! * Linux: a Nautilus script and a KDE/Dolphin service menu
//! * Windows: Explorer context-menu entries for files and folders (via `reg.exe`)
//!
//! Each target just runs `autosort --sort <paths>`. The file contents are generated by pure functions so
//! they can be tested on any platform.

use std::fs;
use std::path::{Path, PathBuf};

pub const MENU_TEXT: &str = "Sort with AutoSort";

fn xml_escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;")
}

fn shell_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', "'\\''"))
}

// -------------------------------------------------------------------------------- macOS

/// `(relative path, contents)` of the Quick Action bundle.
pub fn macos_workflow_files(exe: &str) -> Vec<(&'static str, String)> {
    let command = format!("{} --sort \"$@\"", shell_quote(exe));
    let info = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>NSServices</key>
    <array>
        <dict>
            <key>NSMenuItem</key>
            <dict><key>default</key><string>{MENU_TEXT}</string></dict>
            <key>NSMessage</key><string>runWorkflowAsService</string>
            <key>NSRequiredContext</key>
            <dict><key>NSApplicationIdentifier</key><string>com.apple.finder</string></dict>
            <key>NSSendFileTypes</key>
            <array><string>public.item</string></array>
        </dict>
    </array>
</dict>
</plist>
"#
    );
    let wflow = format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>AMApplicationBuild</key><string>523</string>
    <key>AMApplicationVersion</key><string>2.10</string>
    <key>AMDocumentVersion</key><string>2</string>
    <key>actions</key>
    <array>
        <dict>
            <key>action</key>
            <dict>
                <key>AMAccepts</key>
                <dict>
                    <key>Container</key><string>List</string>
                    <key>Optional</key><true/>
                    <key>Types</key><array><string>com.apple.cocoa.string</string></array>
                </dict>
                <key>AMActionVersion</key><string>2.0.3</string>
                <key>AMApplication</key><array><string>Automator</string></array>
                <key>AMParameterProperties</key>
                <dict>
                    <key>COMMAND_STRING</key><dict/>
                    <key>CheckedForUserDefaultShell</key><dict/>
                    <key>inputMethod</key><dict/>
                    <key>shell</key><dict/>
                    <key>source</key><dict/>
                </dict>
                <key>AMProvides</key>
                <dict>
                    <key>Container</key><string>List</string>
                    <key>Types</key><array><string>com.apple.cocoa.string</string></array>
                </dict>
                <key>ActionBundlePath</key><string>/System/Library/Automator/Run Shell Script.action</string>
                <key>ActionName</key><string>Run Shell Script</string>
                <key>ActionParameters</key>
                <dict>
                    <key>COMMAND_STRING</key><string>{cmd}</string>
                    <key>CheckedForUserDefaultShell</key><true/>
                    <key>inputMethod</key><integer>1</integer>
                    <key>shell</key><string>/bin/zsh</string>
                    <key>source</key><string></string>
                </dict>
                <key>BundleIdentifier</key><string>com.apple.RunShellScript</string>
                <key>CFBundleVersion</key><string>2.0.3</string>
                <key>CanShowSelectedItemsWhenRun</key><false/>
                <key>CanShowWhenRun</key><true/>
                <key>Category</key><array><string>AMCategoryUtilities</string></array>
                <key>Class Name</key><string>RunShellScriptAction</string>
                <key>UnlocalizedApplications</key><array><string>Automator</string></array>
                <key>isViewVisible</key><integer>1</integer>
            </dict>
            <key>isViewVisible</key><integer>1</integer>
        </dict>
    </array>
    <key>connectors</key><dict/>
    <key>workflowMetaData</key>
    <dict>
        <key>applicationBundleIDsByPath</key><dict/>
        <key>applicationPaths</key><array/>
        <key>inputTypeIdentifier</key><string>com.apple.Automator.fileSystemObject</string>
        <key>outputTypeIdentifier</key><string>com.apple.Automator.nothing</string>
        <key>presentationMode</key><integer>15</integer>
        <key>processesInput</key><integer>0</integer>
        <key>serviceInputTypeIdentifier</key><string>com.apple.Automator.fileSystemObject</string>
        <key>serviceOutputTypeIdentifier</key><string>com.apple.Automator.nothing</string>
        <key>serviceProcessesInput</key><integer>0</integer>
        <key>systemImageName</key><string>NSActionTemplate</string>
        <key>useAutomaticInputType</key><integer>0</integer>
        <key>workflowTypeIdentifier</key><string>com.apple.Automator.servicesMenu</string>
    </dict>
</dict>
</plist>
"#,
        cmd = xml_escape(&command)
    );
    vec![("Contents/Info.plist", info), ("Contents/document.wflow", wflow)]
}

pub fn macos_workflow_dir(home: &Path) -> PathBuf {
    home.join("Library/Services").join(format!("{MENU_TEXT}.workflow"))
}

// -------------------------------------------------------------------------------- Linux

/// Nautilus ("Scripts") entry. Nautilus passes the selection in `NAUTILUS_SCRIPT_SELECTED_FILE_PATHS`,
/// one path per line.
pub fn nautilus_script(exe: &str) -> String {
    format!(
        "#!/bin/sh\n# Installed by AutoSort\nIFS='\n'\nset -- $NAUTILUS_SCRIPT_SELECTED_FILE_PATHS\nexec {} --sort \"$@\"\n",
        shell_quote(exe)
    )
}

/// KDE / Dolphin service menu.
pub fn kde_service_menu(exe: &str) -> String {
    format!(
        "[Desktop Entry]\nType=Service\nServiceTypes=KonqPopupMenu/Plugin\nMimeType=all/allfiles;inode/directory;\nActions=autosort_sort;\n\n[Desktop Action autosort_sort]\nName={MENU_TEXT}\nExec={} --sort %F\n",
        shell_quote(exe)
    )
}

// ------------------------------------------------------------------------------- Windows

/// `reg add` argument lists, in order.
pub fn windows_reg_commands(exe: &str) -> Vec<Vec<String>> {
    let mut cmds = Vec::new();
    for base in ["HKCU\\Software\\Classes\\*\\shell\\AutoSort", "HKCU\\Software\\Classes\\Directory\\shell\\AutoSort"] {
        cmds.push(vec!["add".into(), base.into(), "/ve".into(), "/d".into(), MENU_TEXT.into(), "/f".into()]);
        cmds.push(vec![
            "add".into(),
            format!("{base}\\command"),
            "/ve".into(),
            "/d".into(),
            format!("\"{exe}\" --sort \"%1\""),
            "/f".into(),
        ]);
    }
    cmds
}

pub fn windows_unreg_commands() -> Vec<Vec<String>> {
    ["HKCU\\Software\\Classes\\*\\shell\\AutoSort", "HKCU\\Software\\Classes\\Directory\\shell\\AutoSort"]
        .into_iter()
        .map(|k| vec!["delete".to_string(), k.to_string(), "/f".to_string()])
        .collect()
}

// ----------------------------------------------------------------------------- install

fn write_file(path: &Path, contents: &str, executable: bool) -> Result<(), String> {
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir).map_err(|e| format!("cannot create {}: {e}", dir.display()))?;
    }
    fs::write(path, contents).map_err(|e| format!("cannot write {}: {e}", path.display()))?;
    #[cfg(unix)]
    if executable {
        use std::os::unix::fs::PermissionsExt;
        let _ = fs::set_permissions(path, fs::Permissions::from_mode(0o755));
    }
    let _ = executable;
    Ok(())
}

/// Files this platform's integration consists of, relative to the user's home (or app-data) directory.
fn targets(home: &Path, os: &str) -> Vec<PathBuf> {
    match os {
        "macos" => vec![macos_workflow_dir(home)],
        "linux" => vec![
            home.join(".local/share/nautilus/scripts").join(MENU_TEXT),
            home.join(".local/share/kio/servicemenus/autosort.desktop"),
        ],
        _ => vec![],
    }
}

/// Installs the right-click action for the current user. Returns a message for the person.
pub fn install(exe: &Path) -> Result<String, String> {
    let home = directories::BaseDirs::new().map(|d| d.home_dir().to_path_buf()).ok_or("cannot find your home folder")?;
    install_in(&home, std::env::consts::OS, exe)
}

pub fn install_in(home: &Path, os: &str, exe: &Path) -> Result<String, String> {
    let exe = exe.to_string_lossy().into_owned();
    match os {
        "macos" => {
            let dir = macos_workflow_dir(home);
            for (rel, contents) in macos_workflow_files(&exe) {
                write_file(&dir.join(rel), &contents, false)?;
            }
            // ask macOS to notice the new service (harmless if it is already picked up)
            let _ = std::process::Command::new("/System/Library/CoreServices/pbs").arg("-update").status();
            Ok(format!(
                "Installed “{MENU_TEXT}”. Right-click a file or folder in Finder → Quick Actions. If it is missing, enable it in System Settings → Keyboard → Keyboard Shortcuts → Services → Files and Folders."
            ))
        }
        "linux" => {
            let script = &targets(home, os)[0];
            write_file(script, &nautilus_script(&exe), true)?;
            let kde = &targets(home, os)[1];
            write_file(kde, &kde_service_menu(&exe), true)?;
            Ok(format!("Installed “{MENU_TEXT}” for Nautilus (right-click → Scripts) and Dolphin (right-click → Actions)."))
        }
        "windows" => {
            for args in windows_reg_commands(&exe) {
                let status = std::process::Command::new("reg").args(&args).status().map_err(|e| format!("could not run reg.exe: {e}"))?;
                if !status.success() {
                    return Err("could not update the Windows registry".into());
                }
            }
            Ok(format!("Installed “{MENU_TEXT}” in the Explorer right-click menu (on Windows 11: Show more options)."))
        }
        other => Err(format!("not supported on {other}")),
    }
}

pub fn uninstall() -> Result<String, String> {
    let home = directories::BaseDirs::new().map(|d| d.home_dir().to_path_buf()).ok_or("cannot find your home folder")?;
    uninstall_in(&home, std::env::consts::OS)
}

pub fn uninstall_in(home: &Path, os: &str) -> Result<String, String> {
    match os {
        "macos" | "linux" => {
            for t in targets(home, os) {
                if t.is_dir() {
                    let _ = fs::remove_dir_all(&t);
                } else if t.exists() {
                    let _ = fs::remove_file(&t);
                }
            }
            if os == "macos" {
                let _ = std::process::Command::new("/System/Library/CoreServices/pbs").arg("-update").status();
            }
            Ok(format!("Removed “{MENU_TEXT}”."))
        }
        "windows" => {
            for args in windows_unreg_commands() {
                let _ = std::process::Command::new("reg").args(&args).status();
            }
            Ok(format!("Removed “{MENU_TEXT}”."))
        }
        other => Err(format!("not supported on {other}")),
    }
}

pub fn is_installed() -> bool {
    let Some(home) = directories::BaseDirs::new().map(|d| d.home_dir().to_path_buf()) else { return false };
    is_installed_in(&home, std::env::consts::OS)
}

pub fn is_installed_in(home: &Path, os: &str) -> bool {
    match os {
        "windows" => std::process::Command::new("reg")
            .args(["query", "HKCU\\Software\\Classes\\*\\shell\\AutoSort"])
            .output()
            .map(|o| o.status.success())
            .unwrap_or(false),
        _ => targets(home, os).iter().any(|p| p.exists()),
    }
}
